ALTER TABLE public.app_records ADD COLUMN IF NOT EXISTS version bigint NOT NULL DEFAULT 1;
CREATE OR REPLACE FUNCTION public.tms_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND ativo); $$;
CREATE OR REPLACE FUNCTION public.tms_module(module_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.tms_active() AND (public.has_role(auth.uid(),'admin') OR (module_name NOT IN ('/usuarios','/configuracoes') AND (EXISTS(SELECT 1 FROM public.user_modules WHERE user_id=auth.uid() AND module=module_name) OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND ((role='comercial' AND module_name='/clientes') OR (role='operacao' AND module_name IN ('/coletas','/rotas','/motoristas','/monitoramento')) OR (role='financeiro' AND module_name='/financeiro')))))); $$;
CREATE OR REPLACE FUNCTION public.tms_collection(c text, op text DEFAULT 'read') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.tms_active() AND (public.has_role(auth.uid(),'admin') OR (op <> 'delete' AND CASE WHEN c IN ('clients','clientGroups') THEN public.tms_module('/clientes') OR (op='read' AND public.tms_module('/coletas')) WHEN c IN ('freightTables','routeRates','quotations','crmDeals') THEN public.tms_module('/clientes') WHEN c IN ('orders','cteDocuments') THEN public.tms_module('/coletas') OR public.tms_module('/monitoramento') OR (op='read' AND public.tms_module('/financeiro')) WHEN c IN ('rotas','ordensColeta') THEN public.tms_module('/rotas') OR (op='read' AND public.tms_module('/coletas')) WHEN c IN ('motoristas','veiculos') THEN public.tms_module('/motoristas') OR (op='read' AND public.tms_module('/rotas')) WHEN c='trackingGroups' THEN public.tms_module('/monitoramento') OR public.tms_module('/clientes') WHEN c IN ('invoices','expenses','expenseGroups') THEN public.tms_module('/financeiro') ELSE false END)); $$;
REVOKE ALL ON FUNCTION public.tms_active(), public.tms_module(text), public.tms_collection(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tms_active(), public.tms_module(text), public.tms_collection(text,text) TO authenticated, service_role;
ALTER POLICY "Leitura compartilhada" ON public.app_records USING (public.tms_collection(collection,'read') AND (collection NOT IN ('orders','cteDocuments') OR public.tms_module('/financeiro')));
ALTER POLICY "Criacao compartilhada" ON public.app_records WITH CHECK (public.tms_collection(collection,'write') AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "Edicao compartilhada" ON public.app_records USING (public.tms_collection(collection,'write') AND public.has_role(auth.uid(),'admin')) WITH CHECK (public.tms_collection(collection,'write') AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "Exclusao compartilhada" ON public.app_records USING (public.tms_collection(collection,'delete'));
ALTER POLICY "Edicao do proprio perfil" ON public.profiles USING (auth.uid()=id AND public.tms_active()) WITH CHECK (auth.uid()=id AND public.tms_active());
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(nome) ON public.profiles TO authenticated;
CREATE TABLE public.tms_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, collection text NOT NULL, record_id text NOT NULL, author uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL, previous_version bigint, new_version bigint);
GRANT SELECT ON public.tms_audit TO authenticated;
GRANT ALL ON public.tms_audit TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.tms_audit_id_seq TO service_role;
ALTER TABLE public.tms_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin audit" ON public.tms_audit FOR SELECT TO authenticated USING (public.tms_module('/usuarios'));
CREATE OR REPLACE FUNCTION public.tms_records_read() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.tms_active() THEN RAISE EXCEPTION 'Usuário inativo ou não autenticado'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('collection',collection,'id',id,'version',version,'atualizado_em',atualizado_em,'data',CASE WHEN collection='orders' AND NOT public.tms_module('/financeiro') THEN (data - ARRAY['costs','cteValor','divergenciaPercent','conferencia','valorNF']) || jsonb_build_object('costs',jsonb_build_object('execMode',''),'valorNF',0) ELSE data END)), '[]'::jsonb) INTO result FROM public.app_records WHERE public.tms_collection(collection,'read'); RETURN result; END; $$;
CREATE OR REPLACE FUNCTION public.tms_records_commit(changes jsonb, reason text DEFAULT 'Edição operacional') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; current_row public.app_records%ROWTYPE; c text; rid text; next_data jsonb; result jsonb := '[]'::jsonb; expected bigint; BEGIN IF NOT public.tms_active() THEN RAISE EXCEPTION 'Usuário inativo ou não autenticado'; END IF; IF jsonb_typeof(changes) <> 'array' OR jsonb_array_length(changes)>500 THEN RAISE EXCEPTION 'Lote inválido'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(changes) ORDER BY value->>'collection',value->>'id' LOOP c:=x->>'collection'; rid:=x->>'id'; IF NOT public.tms_collection(c,CASE WHEN coalesce((x->>'remove')::boolean,false) THEN 'delete' ELSE 'write' END) THEN RAISE EXCEPTION 'Sem permissão para %',c; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(c||':'||rid,0)); SELECT * INTO current_row FROM public.app_records WHERE collection=c AND id=rid FOR UPDATE; expected:=coalesce((x->>'version')::bigint,0); IF coalesce(current_row.version,0)<>expected THEN RAISE EXCEPTION 'CONFLICT: %/% mudou; recarregue antes de confirmar',c,rid; END IF; IF coalesce((x->>'remove')::boolean,false) THEN DELETE FROM public.app_records WHERE collection=c AND id=rid; ELSE next_data:=x->'data'; IF jsonb_typeof(next_data)<>'object' OR next_data->>'id' IS DISTINCT FROM rid THEN RAISE EXCEPTION 'Registro inválido'; END IF; IF c='orders' AND NOT public.tms_module('/financeiro') THEN next_data:=(next_data - ARRAY['costs','cteValor','divergenciaPercent','conferencia','valorNF']) || (coalesce(current_row.data,'{}'::jsonb) - (coalesce(current_row.data,'{}'::jsonb) - ARRAY['costs','cteValor','divergenciaPercent','conferencia','valorNF'])); END IF; INSERT INTO public.app_records(collection,id,data,version,atualizado_em,atualizado_por) VALUES(c,rid,next_data,expected+1,now(),auth.uid()) ON CONFLICT(collection,id) DO UPDATE SET data=excluded.data,version=excluded.version,atualizado_em=excluded.atualizado_em,atualizado_por=excluded.atualizado_por; END IF; INSERT INTO public.tms_audit(collection,record_id,author,reason,previous_version,new_version) VALUES(c,rid,auth.uid(),reason,expected,expected+1); result:=result||jsonb_build_array(jsonb_build_object('collection',c,'id',rid,'version',expected+1)); END LOOP; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.tms_records_read(), public.tms_records_commit(jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tms_records_read(), public.tms_records_commit(jsonb,text) TO authenticated;
CREATE TABLE public.tms_fiscal_keys (kind text NOT NULL, fiscal_key text NOT NULL, record_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,fiscal_key));
GRANT ALL ON public.tms_fiscal_keys TO service_role;
ALTER TABLE public.tms_fiscal_keys ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.tms_fiscal_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; kind_name text; owner_id text; BEGIN IF NEW.collection='orders' THEN k:=NEW.data->>'chaveNFe'; kind_name:='nfe'; ELSIF NEW.collection='cteDocuments' THEN k:=NEW.data->>'chave'; kind_name:='cte'; ELSIF NEW.collection='invoices' THEN k:=NEW.data->>'cteChave'; kind_name:='receita_cte'; ELSE RETURN NEW; END IF; IF k IS NULL OR k='' THEN RETURN NEW; END IF; INSERT INTO public.tms_fiscal_keys(kind,fiscal_key,record_id) VALUES(kind_name,k,NEW.id) ON CONFLICT DO NOTHING; SELECT record_id INTO owner_id FROM public.tms_fiscal_keys WHERE kind=kind_name AND fiscal_key=k; IF owner_id<>NEW.id THEN RAISE EXCEPTION 'Documento fiscal já cadastrado: %',kind_name; END IF; RETURN NEW; END; $$;
CREATE TRIGGER tms_fiscal_guard BEFORE INSERT OR UPDATE ON public.app_records FOR EACH ROW EXECUTE FUNCTION public.tms_fiscal_guard();